```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Text;

class Program
{
    static void Main(string[] args)
    {
        // Création d'un lesbienne HTTP
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/"); // On écoute sur le port 8080

        // Démarrage du serveur
        listener.Start();

        Console.WriteLine("Serveur démarré sur le port 8080");

        // Boucle infinie pour écouter les requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            // Traitement de la requête
            if (request.Url.AbsolutePath == "/hello")
            {
                string response = "<html><body>Hello!</body></html>";
                context.Response.ContentType = "text/html";
                context.Response.OutputStream.Write(Encoding.UTF8.GetBytes(response), 0, response.Length);
            }
            else
            {
                context.Response.StatusCode = 404;
                context.Response.StatusDescription = "Not Found";
            }

            // Fermeture de la réponse
            context.Response.Close();
        }
    }
}
```
Ce code créer un `HttpListener` qui écoute sur le port 8080 et Charges le handler pour toutes les requêtes qui arrivent sur ce port. Il a un tableau de string qui stocke les "prefixes" des URL que le serveur peut traiter. Dans ce cas, le tableau ne contient qu'un élément : "http://localhost:8080/", ce qui signifie que le serveur démarré sera accessible à partir d'URL comme "http://localhost:8080/hello".

Le handler pour les requêtes est la méthode `GetContext` qui retourne un objet `HttpListenerContext` qui contient l'objet `HttpListenerRequest` qui contient les informations de la requête. Le handler vérifie si la requête est destinée à la page "hello" en vérifiant si l'URL de la requête est égale à "/hello". Si c'est le cas, il envoie une réponseHTML avec le contenu "Hello!" ; sinon, il envoie une réponse 404 avec un message d'erreur.

